import{_ as r,o,c as a,a3 as t}from"./chunks/framework.DdpBa4_E.js";const k=JSON.parse('{"title":"百尺竿头，更进一步","description":"","frontmatter":{},"headers":[],"relativePath":"books/docker-guide/03-百尺竿头更进一步.md","filePath":"books/docker-guide/03-百尺竿头更进一步.md","lastUpdated":1794316978000}'),c={name:"books/docker-guide/03-百尺竿头更进一步.md"};function n(l,e,s,p,i,d){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="百尺竿头-更进一步" tabindex="-1">百尺竿头，更进一步 <a class="header-anchor" href="#百尺竿头-更进一步" aria-label="Permalink to &quot;百尺竿头，更进一步&quot;">​</a></h1><p>在这本小册里，我们从 Docker 最基础的知识谈起，介绍了 Docker 的核心组成部分以及操作这些功能的命令与方法，其后又讲解了开发中最常用的 Docker Compose，并完整的展示了通过它们搭建开发环境的过程。</p><p>然而 Docker 的生态太过丰富，不仅是 Docker 相关的知识浩如烟海，就连开发中所能使用到的技巧也不可胜数。虽然我尽心总结，但这本小册里肯定还存在许多欠缺和匮乏之处。</p><p>好在小册的结构经过我精心编排，形成了一条有逻辑的脉络，这能够帮助大家由浅入深的逐步掌握 Docker 及其与它相关的知识。</p><p>大家可以在阅读每一小节后，对其中仍有疑惑之处，可以直接加入到这本小册的微信群中，直接向大家提问并参与我们的交流。同时，如果你在开发中还有对工作效率或其他方面有提高的 Docker 使用经验技巧，也欢迎加入到微信群中，与大家分享。</p><p>另外，大家可以通过留言或在微信群中提问的方式，说出你还想了解的知识点或使用技巧，在这本小册后面，我会选择大家比较关注的一些知识或问题专门开辟篇幅进行讲解。</p><h2 id="知识延伸" tabindex="-1">知识延伸 <a class="header-anchor" href="#知识延伸" aria-label="Permalink to &quot;知识延伸&quot;">​</a></h2><p>在小册里我们谈到了很多关于 docker 命令和 docker-compose 命令的使用方法，但这两个命令中还包含了大量的使用方法，大家可以通过阅读这两个命令的手册来获得更详细的解读。</p><ul><li><a href="https://docs.docker.com/engine/reference/run/" target="_blank" rel="noreferrer">docker : https://docs.docker.com/engine/reference/run/</a></li><li><a href="https://docs.docker.com/compose/reference/overview/" target="_blank" rel="noreferrer">docker-compose : https://docs.docker.com/compose/reference/overview/</a></li></ul><p>如果还希望了解更多关于 Docker 的知识，我想下面的这些社区会对你很有帮助。</p><ul><li><a href="https://juejin.im/tag/Docker" target="_blank" rel="noreferrer">掘金</a></li><li><a href="https://segmentfault.com/t/docker" target="_blank" rel="noreferrer">Segmentfault</a></li><li><a href="https://www.oschina.net/question/tag/docker" target="_blank" rel="noreferrer">开源中国</a></li></ul><h2 id="我的专栏" tabindex="-1">我的专栏 <a class="header-anchor" href="#我的专栏" aria-label="Permalink to &quot;我的专栏&quot;">​</a></h2><p>最后，友情推荐下我自己的微信公众号「虞山脚下」，更多有关技术的知识我会逐渐更新到公众号中。使用微信扫一扫下面的二维码即可到访。</p><p><img src="https://user-gold-cdn.xitu.io/2018/10/8/166530142aefeb7a?w=258&amp;h=258&amp;f=jpeg&amp;s=27874" alt="" loading="lazy"></p><p>也欢迎到访：<a href="https://youmingdot.com" target="_blank" rel="noreferrer">虞山脚下 : https://youmingdot.com</a></p>',15)])])}const h=r(c,[["render",n]]);export{k as __pageData,h as default};
